import { Injectable } from '@angular/core';
import { company } from '../pages/company-master/company-master';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../environments/environments';
@Injectable({
  providedIn: 'root'
})
export class CompanyService {
  private apiUrl = `${environment.apiUrl}/company`; 
  constructor(private http: HttpClient) {}

  getAllCompanies(): Observable<company[]> {
    return this.http.get<company[]>(this.apiUrl);
  }
  getCompanyByID(id: number): Observable<company> {
    return this.http.get<company>(`${this.apiUrl}/${id}`)
  }
  addCompany(product: company): Observable<company> {
  return this.http.post<company>(`${this.apiUrl}/create-company`, product);
}

updateCompany(id: number, product: company): Observable<company> {
  return this.http.put<company>(`${this.apiUrl}/update-company/${id}`, product);
}

deleteCompany(id: number): Observable<void> {
  
  return this.http.delete<void>(`${this.apiUrl}/${id}`);
}

}
